// Package postgres implements user.Store against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/platform/internal/errorx"
	"github.com/garamsh/garam/platform/internal/grn"
	"github.com/garamsh/garam/platform/internal/listfilter"
	"github.com/garamsh/garam/platform/internal/pgxerr"
	"github.com/garamsh/garam/platform/internal/pgxtype"
	"github.com/garamsh/garam/platform/internal/user"
	"github.com/garamsh/garam/platform/internal/user/postgres/db"
)

// Store implements user.Store against PostgreSQL.
type Store struct {
	q *db.Queries
}

// Compile-time check that Store satisfies user.Store.
var _ user.Store = (*Store)(nil)

// New constructs a Postgres-backed user.Store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool)}
}

// Create persists a new User.
func (s *Store) Create(ctx context.Context, u *user.User) error {
	err := s.q.CreateUser(ctx, db.CreateUserParams{
		Grn:       u.GRN.String(),
		Nickname:  u.Nickname,
		Roles:     strs(u.Roles),
		Policies:  strs(u.Policies),
		CreatedAt: pgxtype.Timestamptz(u.CreatedAt),
		UpdatedAt: pgxtype.Timestamptz(u.UpdatedAt),
	})
	return pgxerr.Classify(err, "create", nil, nil)
}

// Get returns the User with the given GRN, or user.ErrUserNotFound.
func (s *Store) Get(ctx context.Context, g grn.GRN) (*user.User, error) {
	row, err := s.q.GetUser(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get", user.ErrUserNotFound, nil)
	}
	return rowToUser(row)
}

// ListByGRNs returns the Users with the given GRNs, ordered by GRN.
// GRNs without a user are absent from the result.
func (s *Store) ListByGRNs(ctx context.Context, grns []grn.GRN) ([]*user.User, error) {
	if len(grns) == 0 {
		return []*user.User{}, nil
	}
	keys := make([]string, 0, len(grns))
	for _, g := range grns {
		keys = append(keys, g.String())
	}
	rows, err := s.q.ListUsersByGRNs(ctx, keys)
	if err != nil {
		return nil, pgxerr.Classify(err, "list by grns", nil, nil)
	}
	users := make([]*user.User, 0, len(rows))
	for _, row := range rows {
		u, err := rowToUser(row)
		if err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, nil
}

// SearchByGRNs returns the Users among grns whose nickname or
// identifier holds n, ordered by GRN.
func (s *Store) SearchByGRNs(ctx context.Context, grns []grn.GRN, n listfilter.Needle) ([]*user.User, error) {
	if len(grns) == 0 {
		return []*user.User{}, nil
	}
	keys := make([]string, 0, len(grns))
	for _, g := range grns {
		keys = append(keys, g.String())
	}
	rows, err := s.q.SearchUsersByGRNs(ctx, db.SearchUsersByGRNsParams{Grns: keys, Pattern: pgxtype.Contains(n.Text())})
	if err != nil {
		return nil, pgxerr.Classify(err, "search by grns", nil, nil)
	}
	users := make([]*user.User, 0, len(rows))
	for _, row := range rows {
		u, err := rowToUser(row)
		if err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, nil
}

// Update applies a Patch and returns the updated User.
func (s *Store) Update(ctx context.Context, g grn.GRN, p user.Patch) (*user.User, error) {
	row, err := s.q.UpdateUser(ctx, db.UpdateUserParams{
		Grn:       g.String(),
		Nickname:  text(p.Nickname),
		Roles:     p.Roles,
		Policies:  p.Policies,
		UpdatedAt: pgxtype.Timestamptz(time.Now().UTC()),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "update", user.ErrUserNotFound, nil)
	}
	return rowToUser(row)
}

// Delete removes the User with the given GRN.
//
// The foreign-key reading is made here because only here is the
// statement known: [pgxerr.Classify] maps 23503 to not found, which is
// what it means for an insert, and on this delete it means the opposite
// — the row is present and something still points at it.
func (s *Store) Delete(ctx context.Context, g grn.GRN) error {
	n, err := s.q.DeleteUser(ctx, g.String())
	if err != nil {
		if pgxerr.IsForeignKeyViolation(err) {
			return user.ErrUserReferenced
		}
		return pgxerr.Classify(err, "delete", nil, nil)
	}
	if n == 0 {
		return user.ErrUserNotFound
	}
	return nil
}

// rowToUser converts a sqlc row into the domain aggregate. A stored
// value that no longer parses is data corruption, hence internal.
func rowToUser(row db.User) (*user.User, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "user row grn", errorx.KindInternal)
	}
	return &user.User{
		GRN:       g,
		Nickname:  row.Nickname,
		Roles:     row.Roles,
		Policies:  row.Policies,
		CreatedAt: row.CreatedAt.Time,
		UpdatedAt: row.UpdatedAt.Time,
	}, nil
}

// strs normalizes a nil slice to empty: pgx encodes a nil slice as// NULL, which the NOT NULL array columns reject.
func strs(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// text converts a *string patch field to a nullable text.
func text(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}
